  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_autonomy_changes_project_role
  ON autonomy_changes(project_id, role_key, created_at DESC);

CREATE TABLE IF NOT EXISTS role_reviews (
